Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void postLoad()
{
    next postLoad();

    CustPackingSlipJour         custPackingSlipJour;
    SalesTable              salesTable;

    select firstonly custPackingSlipJour
       where custPackingSlipJour.PackingSlipId   == this.PackingSlipId
          && custPackingSlipJour.DeliveryDate    == this.DeliveryDate;

    salesTable = SalesTable::find(custPackingSlipJour.SalesId);

    this.AVAPurchOrderDate = salesTable.AVAEDIPurchOrderDate;


}
